const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('node:assert');

// -------------------------------------------------------------------------
// Background steps
// -------------------------------------------------------------------------

Given('the app is loaded', function () {
  // Already loaded by world.js Before hook
  assert.ok(this.document, 'app document should exist');
});

Given('there are no saved todos', function () {
  this.loadApp([]);
});

Given('the new-todo input is focused', function () {
  // The new-todo input should already be focused via autofocus
  // Focus it explicitly for the test
  const input = this.document.querySelector('.new-todo');
  input.focus();
});

// -------------------------------------------------------------------------
// Data table step - "the following todos exist:"
// -------------------------------------------------------------------------

Given('the following todos exist:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = rows.map(function (r) {
    return {
      id: Date.now() + Math.random().toString(36).substr(2, 9),
      title: r.title,
      completed: false
    };
  });
  this.loadApp(todos);
});

// -------------------------------------------------------------------------
// Completion steps
// -------------------------------------------------------------------------

Given('the {string} todo is completed', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      stored[i].completed = true;
    }
  }
  this.loadApp(stored);
});

Given('all todos are completed', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    stored[i].completed = true;
  }
  this.loadApp(stored);
});

// -------------------------------------------------------------------------
// Action steps (When)
// -------------------------------------------------------------------------

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  // Dispatch input event so app can listen if needed
  const evt = new this.window.Event('input', { bubbles: true });
  input.dispatchEvent(evt);
});

When('I press Enter', function () {
  // Check if an edit input exists and the app is in editing mode
  const inEdit = this.document.querySelector('.todo-list li.editing');
  const input = inEdit
    ? this.document.querySelector('.edit')
    : this.document.querySelector('.new-todo');
  const evt = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(evt);
});

When('I press Escape', function () {
  const editInput = this.document.querySelector('.edit');
  if (!editInput) return;
  const evt = new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    which: 27,
    bubbles: true
  });
  editInput.dispatchEvent(evt);
});

When('I click the toggle checkbox for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const toggle = items[i].querySelector('.toggle');
      toggle.click();
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I click the destroy button for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const destroy = items[i].querySelector('.destroy');
      destroy.click();
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I click the toggle-all checkbox', function () {
  const toggleAllCheckbox = this.document.querySelector('.toggle-all');
  // happy-dom click does not reliably fire change on checkboxes.
  // Dispatch change directly; the app handler does not read checkbox state.
  toggleAllCheckbox.checked = true;
  const evt = new this.window.Event('change', { bubbles: true });
  toggleAllCheckbox.dispatchEvent(evt);
});

When('I click the {string} button', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    btn.click();
  } else {
    assert.fail('Unknown button: ' + buttonText);
  }
});

When('I view the todo-count', function () {
  // Just a no-op assertion trigger, the count is always visible
});

When('I double-click the label for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const evt = new this.window.MouseEvent('dblclick', {
        bubbles: true,
        detail: 2
      });
      label.dispatchEvent(evt);
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I change the edit input value to {string}', function (text) {
  const editInput = this.document.querySelector('.edit');
  editInput.value = text;
  // Dispatch input event
  const evt = new this.window.Event('input', { bubbles: true });
  editInput.dispatchEvent(evt);
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.edit');
  const evt = new this.window.Event('blur', { bubbles: true });
  editInput.dispatchEvent(evt);
});

When('I navigate to the {string} filter', function (filterName) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const hash = filterMap[filterName];
  assert.ok(hash, 'Unknown filter: ' + filterName);
  this.navigate(hash);
});

When('I reload the app', function () {
  // Preserve localStorage state across reload (new window has its own empty storage)
  const todos = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  const filter = this.localStorage.getItem('todos-vanillajs-filter');
  const extra = {};
  if (filter !== null) extra['todos-vanillajs-filter'] = filter;
  this.loadApp(todos, extra);
});

// -------------------------------------------------------------------------
// Assertion steps (Then)
// -------------------------------------------------------------------------

Then('a todo item with the title {string} appears in the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      found = true;
      break;
    }
  }
  assert.ok(found, 'Expected todo item "' + title + '" to appear in the list');
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'new-todo input should be cleared');
});

Then('no new todo item is added', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  // The todo-list might be empty if no items
  // Just ensure count hasn't changed from what we expect
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  assert.strictEqual(stored.length, 0, 'No todos should be stored');
});

Then('the {string} todo item has the class {string}', function (title, className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(items[i].classList.contains(className),
        'Expected "' + title + '" to have class "' + className + '"');
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

Then('the {string} todo item does not have the class {string}', function (title, className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(!items[i].classList.contains(className),
        'Expected "' + title + '" not to have class "' + className + '"');
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

Then('its toggle checkbox is checked', function () {
  // Use the last toggle that was clicked
  const toggles = this.document.querySelectorAll('.todo-list .toggle');
  let allChecked = true;
  for (let i = 0; i < toggles.length; i++) {
    if (!toggles[i].checked) allChecked = false;
  }
  assert.ok(allChecked, 'toggle should be checked');
});

Then('its toggle checkbox is not checked', function () {
  const toggles = this.document.querySelectorAll('.todo-list .toggle');
  let anyChecked = false;
  for (let i = 0; i < toggles.length; i++) {
    if (toggles[i].checked) anyChecked = true;
  }
  assert.ok(!anyChecked, 'toggle should not be checked');
});

Then('the {string} todo item is removed from the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.fail('Expected "' + title + '" to be removed from the list');
    }
  }
  // Also check localStorage
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      assert.fail('Expected "' + title + '" to be removed from localStorage');
    }
  }
});

Then('the {string} todo item is replaced by a todo item with the title {string}',
  function (oldTitle, newTitle) {
    const items = this.document.querySelectorAll('.todo-list li');
    let foundOld = false;
    let foundNew = false;
    for (let i = 0; i < items.length; i++) {
      const label = items[i].querySelector('label');
      if (label) {
        if (label.textContent === oldTitle) foundOld = true;
        if (label.textContent === newTitle) foundNew = true;
      }
    }
    assert.ok(!foundOld, 'Old title "' + oldTitle + '" should not appear');
    assert.ok(foundNew, 'New title "' + newTitle + '" should appear');
  });

Then('the {string} todo item still has the title {string}', function (expectedTitle, currentTitle) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === expectedTitle) {
      assert.strictEqual(label.textContent, currentTitle,
        'Title should remain "' + currentTitle + '"');
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + expectedTitle);
});

Then('all todo items have the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'There should be todo items');
  for (let i = 0; i < items.length; i++) {
    assert.ok(items[i].classList.contains(className),
      'Item ' + i + ' should have class "' + className + '"');
  }
});

Then('no todo items have the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    assert.ok(!items[i].classList.contains(className),
      'Item ' + i + ' should not have class "' + className + '"');
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  assert.ok(toggleAll.checked, 'toggle-all should be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  assert.ok(!toggleAll.checked, 'toggle-all should not be checked');
});

Then('the count shows {string}', function (count) {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'todo-count strong element should exist');
  assert.strictEqual(strong.textContent, count,
    'Count should be ' + count + ', got ' + strong.textContent);
});

Then('the count text says {string}', function (text) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'todo-count element should exist');
  // Check that the text content contains the expected word
  assert.ok(countEl.textContent.indexOf(text) !== -1,
    'Count text should contain "' + text + '", got "' + countEl.textContent + '"');
});

Then('the {string} button is not visible', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    assert.ok(btn, 'clear-completed button should exist');
    assert.strictEqual(btn.style.display, 'none',
      'clear-completed should be hidden');
  } else {
    assert.fail('Unknown button: ' + buttonText);
  }
});

Then('the {string} button is visible', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    assert.ok(btn, 'clear-completed button should exist');
    assert.ok(btn.style.display !== 'none' && btn.style.display !== '',
      'clear-completed should be visible');
  } else {
    assert.fail('Unknown button: ' + buttonText);
  }
});

Then('the section with class {string} is not visible', function (className) {
  const el = this.document.querySelector('.' + className);
  assert.ok(el, 'Element with class "' + className + '" should exist');
  assert.strictEqual(el.style.display, 'none',
    'Element "' + className + '" should be hidden');
});

Then('the section with class {string} is visible', function (className) {
  const el = this.document.querySelector('.' + className);
  assert.ok(el, 'Element with class "' + className + '" should exist');
  assert.ok(el.style.display !== 'none' && el.style.display !== '',
    'Element "' + className + '" should be visible');
});

Then('the footer element is not visible', function () {
  const el = this.document.querySelector('.footer');
  assert.ok(el, 'Footer should exist');
  assert.strictEqual(el.style.display, 'none', 'Footer should be hidden');
});

Then('the footer element is visible', function () {
  const el = this.document.querySelector('.footer');
  assert.ok(el, 'Footer should exist');
  assert.ok(el.style.display !== 'none' && el.style.display !== '',
    'Footer should be visible');
});

Then('the {string} filter link has the class {string}', function (filterName, className) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const href = filterMap[filterName];
  assert.ok(href, 'Unknown filter: ' + filterName);
  const links = this.document.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].getAttribute('href') === href) {
      assert.ok(links[i].classList.contains(className),
        'Filter link "' + filterName + '" should have class "' + className + '"');
      return;
    }
  }
  assert.fail('Could not find filter link with href: ' + href);
});

Then('the {string} filter link does not have the class {string}', function (filterName, className) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const href = filterMap[filterName];
  assert.ok(href, 'Unknown filter: ' + filterName);
  const links = this.document.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].getAttribute('href') === href) {
      assert.ok(!links[i].classList.contains(className),
        'Filter link "' + filterName + '" should not have class "' + className + '"');
      return;
    }
  }
});

Then('I see {int} todo item(s)', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count,
    'Expected ' + count + ' todo items, got ' + items.length);
});

Then('the {string} todo item is not visible', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(items[i].style.display === 'none',
        'Todo "' + title + '" should not be visible');
      return;
    }
  }
  // Not in list at all is also acceptable for "not visible"
});

Then('navigating to the {string} filter shows {int} todo item(s)', function (filterName, count) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const hash = filterMap[filterName];
  this.navigate(hash);
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count,
    'Expected ' + count + ' todo items in ' + filterName + ' filter');
});

// -------------------------------------------------------------------------
// Persistence steps
// -------------------------------------------------------------------------

Then('localStorage has a key matching {string}', function (pattern) {
  const keys = Object.keys(this.localStorage);
  let found = false;
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].indexOf('todos-') === 0) {
      found = true;
      break;
    }
  }
  assert.ok(found, 'localStorage should have a key starting with "todos-"');
});

Then('the stored value is a non-empty JSON array', function () {
  const stored = this.localStorage.getItem('todos-vanillajs');
  assert.ok(stored, 'localStorage should have a stored value');
  const parsed = JSON.parse(stored);
  assert.ok(Array.isArray(parsed), 'Stored value should be an array');
  assert.ok(parsed.length > 0, 'Stored array should not be empty');
});

Then('the first stored todo has a title {string}', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  assert.ok(stored.length > 0, 'Should have stored todos');
  assert.strictEqual(stored[0].title, title,
    'First stored todo title should be "' + title + '"');
});

Then('the first stored todo is not completed', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  assert.ok(stored.length > 0, 'Should have stored todos');
  assert.strictEqual(stored[0].completed, false,
    'First stored todo should not be completed');
});

Then('the first stored todo has an id', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  assert.ok(stored.length > 0, 'Should have stored todos');
  assert.ok(stored[0].id !== undefined && stored[0].id !== null,
    'First stored todo should have an id');
});

Then('the stored todo with title {string} is completed', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      assert.strictEqual(stored[i].completed, true,
        'Stored todo "' + title + '" should be completed');
      return;
    }
  }
  assert.fail('Could not find stored todo with title: ' + title);
});

Then('the stored todos array is empty', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  assert.strictEqual(stored.length, 0, 'Stored todos should be empty');
});

Then('the stored todo with title {string} exists', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      return;
    }
  }
  assert.fail('Could not find stored todo with title: ' + title);
});

Then('the first todo item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length >= 1, 'At least 1 todo item should exist');
  const label = items[0].querySelector('label');
  assert.ok(label, 'First item should have a label');
  assert.strictEqual(label.textContent, title,
    'First todo should have title "' + title + '"');
});

Then('the second todo item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length >= 2, 'At least 2 todo items should exist');
  const label = items[1].querySelector('label');
  assert.ok(label, 'Second item should have a label');
  assert.strictEqual(label.textContent, title,
    'Second todo should have title "' + title + '"');
});

// -------------------------------------------------------------------------
// Conformance steps (watch 4)
// -------------------------------------------------------------------------

Given('the app source at {string}', function (filePath) {
  const fs = require('node:fs');
  const fullPath = require('node:path').resolve(__dirname, '..', '..', filePath);
  this.appSource = fs.readFileSync(fullPath, 'utf8');
  assert.ok(this.appSource.length > 0, 'App source should not be empty');
});

When('the conformance verifier checks the render function', function () {
  const source = this.appSource;
  // The conformance verifier checks that render does NOT replace all todoList child nodes.
  // Using removeChild on every child destroys element identity, which causes browser
  // element references to detach. Mutate existing nodes in place instead.
  this.conformanceViolations = [];
  var lines = source.split('\n');
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    // Check for removeChild loop on todoList (destroys all child nodes)
    if (/todoList\.firstChild/.test(line) && /todoList\.removeChild/.test(lines[i + 1] || '')) {
      this.conformanceViolations.push({ line: i + 1, text: line.trim() });
    }
  }
});

When('the conformance verifier checks the edit handlers', function () {
  const source = this.appSource;
  // The conformance verifier checks that the blur handler on edit inputs does NOT call render().
  // Calling render() from a blur handler destroys the editing node while the browser event
  // lifecycle is still processing it, causing a removeChild failure.
  this.conformanceViolations = [];
  var lines = source.split('\n');
  for (var idx = 0; idx < lines.length; idx++) {
    var ln = lines[idx];
    // Check that the blur handler does not call render() directly
    if (/function handleEditBlur/.test(ln)) {
      // Look through the function body for render() calls
      var j = idx + 1;
      while (j < lines.length && !/^\s*\}/.test(lines[j])) {
        if (/render\(\)/.test(lines[j])) {
          this.conformanceViolations.push({ line: j + 1, text: lines[j].trim() });
        }
        j++;
      }
      break;
    }
  }
});

Then('the render function does not replace all todoList child nodes', function () {
  assert.strictEqual(this.conformanceViolations.length, 0,
    'Found ' + this.conformanceViolations.length + ' violation(s): render() must mutate existing ' +
    'todoList child nodes in place instead of removing and recreating them. Violations: ' +
    JSON.stringify(this.conformanceViolations));
});

Then('the render function is not called from a blur handler on the edit input', function () {
  assert.strictEqual(this.conformanceViolations.length, 0,
    'Found ' + this.conformanceViolations.length + ' violation(s): handleEditBlur must not call ' +
    'render() because the browser event lifecycle may still reference the editing node. ' +
    'Violations: ' + JSON.stringify(this.conformanceViolations));
});

Then('there is no stored todo with title {string}', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      assert.fail('Found unexpected stored todo with title: ' + title);
    }
  }
});

Then('I see the list filtered to completed todos', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === 'Task A') {
      assert.fail('Completed todos only should be visible, active items hidden');
    }
  }
  // All visible items should be completed
  for (let i = 0; i < items.length; i++) {
    assert.ok(items[i].classList.contains('completed'),
      'Visible item should be completed');
  }
});

// -------------------------------------------------------------------------
// "the {string} todo item remains in the list" (And step after clear completed)
// -------------------------------------------------------------------------

Then('the {string} todo item remains in the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      found = true;
      break;
    }
  }
  assert.ok(found, 'Expected "' + title + '" to remain in the list');
});

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';

  // --- Model / localStorage ---

  /** @planks("localStorage has a key matching {string}") @planks("the stored value is a non-empty JSON array") @planks("the first stored todo has a title {string}") @planks("the first stored todo is not completed") @planks("the first stored todo has an id") @planks("the stored todo with title {string} is completed") @planks("the stored todos array is empty") @planks("the stored todo with title {string} exists") @planks("there is no stored todo with title {string}") @planks("the first todo item has the title {string}") @planks("the second todo item has the title {string}") @planks("the stored todos array is empty") */
